6532	7673	faq	121	{"id":121,"domanda":"Offrite sconti per acquisti multipli?","risposta":"Sì, offriamo sconti progressivi: 10% su 3 articoli, 15% su 5 o più articoli.","id_doc_elevenlabs":"JSvVzJpLG8pdejPvOLot","id_user":"548f945c-221b-40cd-a78c-f657599722df","azienda":"Z Wave Immobiliare","id_agente":"agent_4401kfg6n9qzeek9qvgynbrpmmt0","date_created":"2026-01-22T14:04:58","date_updated":"2026-01-22T14:54:55","delete":false}	{"azienda":"Z Wave Immobiliare","date_updated":"2026-01-22T14:54:55"}	\N	\N
